ALTER TABLE site_content_items MODIFY item_type ENUM('partner','brand','leader','testimonial','sponsor','collaborator','social') NOT NULL;
CREATE TABLE IF NOT EXISTS customer_media (id CHAR(32) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,original_name VARCHAR(255) NOT NULL,stored_name CHAR(64) NOT NULL,mime VARCHAR(100) NOT NULL,bytes BIGINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),INDEX(order_id));
CREATE TABLE IF NOT EXISTS app_devices (token_hash CHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,pin_hash VARCHAR(255) NOT NULL,password_stamp CHAR(64) NOT NULL,attempts INT NOT NULL DEFAULT 0,locked_until DATETIME NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id));
